INSERT INTO "assessments" VALUES(3,'C0a33e6f36c','compliance','{"findings":[{"requirement_id":"CMN4935-ART14-II","requirement_source":"NORMATIVE","citation":"Res. CMN 4.935/2021, art. 14, inciso II","requirement_text":"Art. 14. O contrato de correspondente deve estabelecer: [...] II - vedação à utilização, pelo contratado, de logomarca ou de outros atributos que sejam similares aos adotados pela instituição contratante em suas agências, postos de atendimento, sítio eletrônico na internet, aplicativo ou outras plataformas de comunicação em rede;","status":"NOT_APPLICABLE_UNLESS_COBAN","observed_evidence":["E-SHOT-VIEWPORT"],"hypothesis":"Uso de logomarca, uso excessivo/desproporcional ou de atributos similares aos adotados pela contratante em seus canais. A norma disciplina correspondentes contratados; o responsável não foi identificado como correspondente.","missing_information":["confirmar se o responsável é correspondente contratado (relação pública da contratante — art. 21 — ou base interna)"],"requires_human_review":true},{"requirement_id":"CMN4935-ART14-III","requirement_source":"NORMATIVE","citation":"Res. CMN 4.935/2021, art. 14, inciso III, alíneas a e b","requirement_text":"Art. 14. O contrato de correspondente deve estabelecer: [...] III - divulgação ao público, pelo contratado, de sua condição de prestador de serviços à instituição contratante, identificada pelo nome com que é conhecida no mercado, com descrição dos produtos e serviços oferecidos e canais de contato da instituição contratante, inclusive de sua ouvidoria, em local visível, em destaque e em formato legível, por meio de: a) sítio eletrônico do correspondente na internet, acessível na página inicial; b) aplicativo e outras plataformas de comunicação em rede do correspondente; [...]","status":"NOT_APPLICABLE_UNLESS_COBAN","observed_evidence":["E-TITLE"],"hypothesis":"Divulgação ao público da condição de prestador de serviços/parceria ausente, insuficiente, ambígua ou sem destaque. A norma disciplina correspondentes contratados; o responsável não foi identificado como correspondente.","missing_information":["confirmar se o responsável é correspondente contratado (relação pública da contratante — art. 21 — ou base interna)","canais de contato/ouvidoria da contratante não observados no material coletado (podem existir em páginas não inspecionadas)"],"requires_human_review":true},{"requirement_id":"CMN4935-ART3","requirement_source":"NORMATIVE","citation":"Res. CMN 4.935/2021, art. 3º","requirement_text":"Art. 3º O correspondente atua por conta e sob as diretrizes da instituição contratante, que assume inteira responsabilidade pelo atendimento prestado aos clientes e usuários por meio do contratado.","status":"NO_INDICATION_OBSERVED","observed_evidence":[],"hypothesis":"","missing_information":[],"requires_human_review":false}],"out_of_scope_notes":["Se o responsável não for correspondente contratado, os indícios podem caracterizar uso indevido de marca ou fraude, fora do escopo da Res. 4.935: avaliar encaminhamento às áreas jurídica/segurança."],"related_controls":[],"limitations":["requisitos contratuais/internos não fornecidos: mapeamento limitado ao texto normativo"],"disclaimer":"Mapeamento indicativo para apoio à auditoria. Não constitui conclusão regulatória; a decisão definitiva pertence à auditoria."}','2026-11-26T04:45:29+00:00',1);
