INSERT INTO "queries" VALUES(1,'simio-20261126-044527-d1c2','grounding','H1-identity:title-brand','Objetivo: Terceiros e promotoras que usam a marca no título da página.
Execute no Google Search as seguintes consultas (dorks):
  - (intitle:"Banco BV" OR intitle:"bv financeira" OR intitle:"BV Financiamentos" OR intitle:"BV Promotora") (financiamento OR crédito OR veículos OR correspondente) -site:bv.com.br -site:bancobv.com.br -site:bvfinanceira.com.br -site:bvinvestimentos.com.br -site:napista.com.br -site:bvopen.com.br -site:meufinanciamentosolar.com.br -site:votorantim.com.br -site:vam.com.br -site:reclameaqui.com.br -site:jusbrasil.com.br -site:jus.br
  - (intitle:"BV Veículos" OR intitle:"Agência BV") (financiamento OR seminovos OR veículos) -site:bv.com.br -site:bancobv.com.br -site:bvfinanceira.com.br -site:bvinvestimentos.com.br -site:napista.com.br -site:bvopen.com.br -site:meufinanciamentosolar.com.br -site:votorantim.com.br -site:vam.com.br -site:reclameaqui.com.br -site:jusbrasil.com.br -site:jus.br
Liste de forma abrangente as páginas públicas encontradas (até 12 resultados distintos), informando para cada uma o nome do estabelecimento/perfil, a URL e como a marca é utilizada (destaque visual, título, feirão, simulador, redes sociais e se há ou não identificação clara de CNPJ e condição de correspondente bancário).','OK',4,NULL,'{}','2026-11-26T04:45:27.492510+00:00');
INSERT INTO "queries" VALUES(2,'simio-20261126-044527-d1c2','grounding','H1-identity:inurl-brand','Objetivo: Sites de terceiros com o nome da marca ou páginas de financiamento na URL.
Execute no Google Search as seguintes consultas (dorks):
  - (inurl:banco-bv OR inurl:bancobv OR inurl:bv-financeira OR inurl:bvfinanceira) (financiamento OR veículos OR crédito OR correspondente) -site:bv.com.br -site:bancobv.com.br -site:bvfinanceira.com.br -site:bvinvestimentos.com.br -site:napista.com.br -site:bvopen.com.br -site:meufinanciamentosolar.com.br -site:votorantim.com.br -site:vam.com.br -site:reclameaqui.com.br -site:jusbrasil.com.br -site:jus.br
  - (inurl:financie OR inurl:financiar) ("bv financeira" OR "Banco BV") (veículos OR simulador OR loja) -site:bv.com.br -site:bancobv.com.br -site:bvfinanceira.com.br -site:bvinvestimentos.com.br -site:napista.com.br -site:bvopen.com.br -site:meufinanciamentosolar.com.br -site:votorantim.com.br -site:vam.com.br -site:reclameaqui.com.br -site:jusbrasil.com.br -site:jus.br
Liste de forma abrangente as páginas públicas encontradas (até 12 resultados distintos), informando para cada uma o nome do estabelecimento/perfil, a URL e como a marca é utilizada (destaque visual, título, feirão, simulador, redes sociais e se há ou não identificação clara de CNPJ e condição de correspondente bancário).','OK',4,NULL,'{}','2026-11-26T04:45:27.492777+00:00');
INSERT INTO "queries" VALUES(3,'simio-20261126-044527-d1c2','grounding','H1-identity:logo-assets','Objetivo: Páginas de financiamento que expõem arquivos de logotipo da marca ou logo antiga (B vermelho / V azul).
Execute no Google Search as seguintes consultas (dorks):
  - (inurl:logo-bv OR "logo-bv" OR "logo-bv-financeira" OR "logo antiga bv" OR "bv logo antiga") (financiamento OR veículos OR crédito) -site:bv.com.br -site:bancobv.com.br -site:bvfinanceira.com.br -site:bvinvestimentos.com.br -site:napista.com.br -site:bvopen.com.br -site:meufinanciamentosolar.com.br -site:votorantim.com.br -site:vam.com.br -site:reclameaqui.com.br -site:jusbrasil.com.br -site:jus.br
  - ("Logo Banco BV" OR "Logo bv financeira" OR "logo BV" OR "logo BV Financeira") (financiamento OR veículos OR consignado) -site:brandsoftheworld.com -site:logospng.org -site:bv.com.br -site:bancobv.com.br -site:bvfinanceira.com.br -site:bvinvestimentos.com.br -site:napista.com.br -site:bvopen.com.br -site:meufinanciamentosolar.com.br -site:votorantim.com.br -site:vam.com.br -site:reclameaqui.com.br -site:jusbrasil.com.br -site:jus.br
  - ("BV Financeira" OR "Banco BV") ("logo antiga" OR "logotipo antigo" OR "marca antiga") -site:bv.com.br -site:bancobv.com.br -site:bvfinanceira.com.br -site:bvinvestimentos.com.br -site:napista.com.br -site:bvopen.com.br -site:meufinanciamentosolar.com.br -site:votorantim.com.br -site:vam.com.br -site:reclameaqui.com.br -site:jusbrasil.com.br -site:jus.br
